package io.github.carlos_emr.carlos.form.model.rehab;

import jakarta.persistence.Entity;
import jakarta.persistence.Table;
import java.util.List;

/**
 * The unchanged {@code formSF36} table: the SF-36 Health Survey questionnaire of the 2004
 * rehabilitation study. Its answer columns are those of {@link SF36Answers}.
 *
 * <p>Generated by {@code scripts/forms/generate_rehab_study_entities.py} from the Flyway
 * baseline; regenerate rather than edit. {@code RehabStudyEntitySchemaContractUnitTest}
 * fails the build when this mapping and the baseline table disagree.</p>
 *
 * @since 2026-11-26
 */
@Entity
@Table(name = "formSF36")
public class FormSF36 extends SF36Answers {
    private static final long serialVersionUID = 1L;

    private static final List<RehabStudyColumn<FormSF36>> COLUMNS = RehabStudyColumn.narrow(answerColumns());

    /** The answer columns in physical order; the shared header is mapped by the superclass. */
    public static List<RehabStudyColumn<FormSF36>> columns() {
        return COLUMNS;
    }
}
